def ddd(q):
 q[1]['options'][3]['explanation']='This frozen dataclass has hashable int/string fields, so hashing succeeds. Frozen dataclasses containing an unhashable field such as a list can still raise TypeError when hashed.'
 q[4]['prompt']+=' Assume A committed the root version and child rows together, and B runs this statement against current committed data (for example PostgreSQL Read Committed).'
 q[4]['options'][1]['explanation']='Optimistic UPDATE statements also take database locks, but A has already committed in this scenario. With a concurrently running A, B could wait before detecting a conflict; stronger isolation can raise a serialization error.'
 q[4]['workedExample']+='\nThis protects child rows only if every writer advances the root version and persists the child changes in the same transaction; check and roll back failed attempts.'
 q[5]['options'][0]['text']='With whole-graph loading and one shared version, loading is large and unrelated order updates contend on that version.'
 q[5]['workedExample']=q[5]['workedExample'].replace('Anything spanning both (like a credit check) can use a domain event or a check at placement time.', 'A strict shared credit limit needs an atomic reservation protocol; an uncoordinated read/check or delayed event alone cannot prevent concurrent overspending.')
 q[7]['prompt']+=' In this example the documented CRM status mapping says 1 and 2 are active.'
 q[7]['workedExample']=q[7]['workedExample'].replace('name=rec["NM_FULL"].title(),', 'name=rec["NM_FULL"],').replace('If the CRM is ever replaced, only the ACL changes.', 'Preserve personal names rather than applying lossy title casing. This snippet assumes a local Customer type with an active field. Replacing the CRM may remain adapter-local only if the new source provides compatible semantics.')
 q[8]['options'][1]['explanation']='This is a common design when temporary pending status and compensation are acceptable. Use reliable event publication and idempotent handlers; separating transactions does not eliminate hot-stock contention.'
 q[8]['workedExample']=q[8]['workedExample'].replace('Message bus delivers the event.', 'Commit the order plus durable outbox event atomically; a relay delivers it with retries and consumers deduplicate.').replace('short inconsistency window', 'an inconsistency window whose duration needs monitoring and recovery').replace('T2 per SKU: `stock.reserve(qty)`; commit.', 'T2 per SKU: atomically reserve idempotently; on partial failure release earlier reservations or apply the chosen compensation policy.')
 q[10]['options'][0]['text']='The example crosses aggregate boundaries. Model an atomic credit-reservation owner or deliberately choose a suitable multi-aggregate transaction if immediate consistency requires it.'
 q[10]['options'][0]['explanation']='A CreditAccount can atomically reserve rights for orders; alternatively a correct database transaction can enforce the invariant. One aggregate per transaction is a design guideline, not a prohibition on valid atomic transactions.'
 q[10]['workedExample']=q[10]['workedExample'].replace('breaks **one aggregate per transaction**.', 'departs from the one-aggregate-per-transaction guideline.').replace('the order references the reservation by id.', 'the order references the reservation by id, with an explicit protocol for pending orders, retries and release.')
questions(b+'sea-ddd.questions.json',ddd,'Correct frozen hashing, optimistic-lock assumptions, customer-credit invariants and durable domain-event delivery.',src)
